package com.valor.auth;
import jakarta.persistence.*; import java.time.*;
@Entity @Table(name="refresh_tokens") public class RefreshToken { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="user_id",nullable=false) User user; @Column(name="token_hash",nullable=false,length=64,columnDefinition="CHAR(64)",unique=true) String tokenHash; @Column(name="expires_at",nullable=false) LocalDateTime expiresAt; @Column(name="revoked_at") LocalDateTime revokedAt; @Column(name="created_at",nullable=false) LocalDateTime createdAt; @PrePersist void p(){createdAt=LocalDateTime.now();} public void setUser(User u){user=u;} public User getUser(){return user;} public void setTokenHash(String v){tokenHash=v;} public String getTokenHash(){return tokenHash;} public void setExpiresAt(LocalDateTime v){expiresAt=v;} public LocalDateTime getExpiresAt(){return expiresAt;} public LocalDateTime getRevokedAt(){return revokedAt;} public void setRevokedAt(LocalDateTime v){revokedAt=v;}}
